import{z as c,x as l,o as t,c as p,q as r,j as s,D as d,d as o,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"动态数组扩容","description":"","frontmatter":{"title":"动态数组扩容","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamic-array.md","filePath":"cs/dynamic-array.md","lastUpdated":1791063341000}'),A={name:"cs/dynamic-array.md"};function B(m,a,h,D,T,u){const n=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="动态数组扩容" tabindex="-1">动态数组扩容 <a class="header-anchor" href="#动态数组扩容" aria-label="Permalink to &quot;动态数组扩容&quot;">​</a></h1><div class="epigraph"><p>长度未知时先留容量；满了就换一块更大的连续区并复制。单次可以线性，一串插入仍可平均常数——账在后课摊还里结。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 第 17.4 节；Knuth, TAOCP 卷 1 整理</footer></div><p><a href="/cs/array-random-access">上一课</a>把按下标读写做成 \\(\\Theta(1)\\)，长度事先已知。真实序列会在尾部增长。本课不重讲基址加偏移。缺口是容量与长度分离：<code>size</code> 个已用槽、<code>cap</code> 个已分配槽；满则分配更大块、复制、释放旧块。本课只钉倍增这一表示，不把势能函数写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>定长数组的合同没有 <code>append</code>。每次增长 1 就 <code>realloc</code> 到 \\(n+1\\) 并复制，则 \\(n\\) 次 append 总代价 \\(\\Theta(n^2)\\)。缺口不是链表——随机访问还要保住——而是<strong>几何增长：<code>cap</code> 乘以常数 \\(\\ge 2\\)</strong>，使得复制次数稀疏。</p><p><span class="marginnote">每次加一代个数：往空表 append 1000 次、每次搬全量，总搬运是 \\(1+2+\\cdots+999\\approx 50\\) 万次元素复制；倍增策略下只需约 2000 次——差 250 倍。这就是 \\(\\Theta(n^2)\\) 与 \\(\\Theta(n)\\) 不是学术细节的地方。</span></p><p>缩小可在 <code>size</code> 远小于 <code>cap</code> 时折半，避免只增不减的泄漏。本课点名，细节与摊还同一套账。</p><p><span class="marginnote">CLRS 用「表扩张」作摊还的主例。本课先有对象；<a href="/cs/amortized-analysis">摊还分析</a>在队列与环形缓冲之后才给分析方法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示：指针、<code>size</code>、<code>cap</code>。<code>append</code>：若 <code>size=cap</code>，申请约 \\(2\\cdot\\mathrm{cap}\\) 的新数组（空表从常数起），复制 <code>size</code> 个元素，替换指针。然后在 <code>size</code> 处写入，<code>size++</code>。按下标仍 \\(\\Theta(1)\\)，中间插入仍 \\(\\Theta(n)\\) 搬移。</p>',10)),(t(),s(E,null,{default:d(()=>[i(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20AP%5B%22append%22%5D%20--%3E%20FULL%5B%22size%20%3D%20cap%20%3F%22%5D%0A%20%20FULL%20--%3E%7C%22%E5%90%A6%22%7C%20PUT%5B%22%E5%86%99%E5%85%A5%20size%2B%2B%22%5D%0A%20%20FULL%20--%3E%7C%22%E6%98%AF%22%7C%20GROW%5B%22%E6%96%B0%20cap%C3%972%EF%BC%8C%E5%A4%8D%E5%88%B6%22%5D%0A%20%20GROW%20--%3E%20PUT%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"迭代器/指针在扩容后失效：基址变了。合同必须写明，否则调用方握着旧地址。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"扩容可以类比搬家：旧屋住满（size=cap），租一间两倍大的新屋，把家具一件件搬过去（复制），再退掉旧屋（释放旧块）。搬家期间你的邮寄地址全作废——这正是「扩容后旧指针与迭代器失效」的直觉来源：它们记的是旧屋的门牌。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[o("随机访问与空间局部性与定长数组相同，直到发生复制：那一次扫完全表，cache 友好但停顿明显。实时路径若不能接受峰值，应预留 "),e("code",null,"cap"),o(" 或改用链表。几何因子太接近 1，复制过频；太大则浪费内存。2 是常见折中。")],-1)),(t(),s(E,null,{default:d(()=>[i(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%A2%9E%E9%95%BF%E5%9B%A0%E5%AD%90%E6%80%8E%E4%B9%88%E9%80%89%22%5D%20--%3E%20F2%5B%22%E5%9B%A0%E5%AD%90%202%EF%BC%9A%E6%80%BB%E5%A4%8D%E5%88%B6%E9%87%8F%E7%BA%A6%202n%EF%BC%8C%E5%B3%B0%E5%80%BC%E5%86%85%E5%AD%98%202%20%E5%80%8D%22%5D%0A%20%20N%20--%3E%20F11%5B%22%E5%9B%A0%E5%AD%90%201.1%EF%BC%9A%E6%80%BB%E5%A4%8D%E5%88%B6%E9%87%8F%E7%BA%A6%2011n%EF%BC%8C%E6%89%A9%E5%AE%B9%E9%A2%91%E7%B9%81%22%5D%0A%20%20N%20--%3E%20F4%5B%22%E5%9B%A0%E5%AD%90%204%EF%BC%9A%E6%80%BB%E5%A4%8D%E5%88%B6%E9%87%8F%E7%BA%A6%201.3n%EF%BC%8C%E5%B3%B0%E5%80%BC%E5%86%85%E5%AD%98%204%20%E5%80%8D%22%5D%0A%20%20F2%20--%3E%20T%5B%22%E5%A4%8D%E5%88%B6%E9%A2%91%E7%8E%87%E4%B8%8E%E5%86%85%E5%AD%98%E6%B5%AA%E8%B4%B9%E4%B9%8B%E9%97%B4%E5%8F%96%E6%8A%98%E4%B8%AD%22%5D%0A%20%20F11%20--%3E%20T%0A%20%20F4%20--%3E%20T%0A"})]),fallback:d(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">初学者容易以为扩容是每次 append 都可能撞上的大事。实际上它只在 size 追上 cap 时发生，且越来越稀：容量 1024 的表要再插 1024 次才扩下一次。真正要盯的是两处——握着旧基址的指针有没有失效，以及实时路径上那一次全表复制的停顿。</span></p><p>与<a href="/cs/locality-principle">局部性原理</a>：新块可能在堆的另一处，NUMA 上甚至换节点；地址计算仍是乘加，延迟不是渐近记号里的 \\(O(1)\\) 纳秒。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不用合计或势能证明摊还 \\(\\Theta(1)\\)，只陈述「复制足够稀」。也不引入分块数组（deque 的块列）——那是后课为两端生长准备的。链表用来买中间插入，不在本课替换动态数组。</p><p>后课默认：尾部增长的连续表用动态数组；按下标仍 \\(\\Theta(1)\\)，扩容时指针失效。中间插入的局部性对照下一课链表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>size</code> 与 <code>cap</code> 分离；满则几何扩容并复制。</li><li>保住随机访问；扩容使旧指针失效。</li><li>摊还证明后置；链表下一课付插入与局部性的另一笔价。</li><li>出处：Cormen et al. 表扩张；Knuth, <em>TAOCP</em> 卷 1。</li></ul>',7))])}const F=c(A,[["render",B]]);export{f as __pageData,F as default};
